func (b *booter) provision(logger *slog.Logger, id identity, bootstrap *sandboxconfig.Config, wire bool) error {
	// The features' groups and env go first, before the account exists, so
	// the account joins groups already there (ADR 26-10-16-423 §5); it also
	// decides which features are off, which the steps below read.
	if b.wireFeatures != nil {
		b.wireFeatures(logger, bootstrap.Features)
	}
	if err := b.ensureUser(id); err != nil {
		return fmt.Errorf("ensure user: %w", err)
	}
	if err := b.ensureAdditionalGroups(id, bootstrap.SandboxGroups()); err != nil {
		return fmt.Errorf("ensure additional groups: %w", err)
	}
	if wire {
		if err := b.wireConfig(); err != nil {
			return fmt.Errorf("wire config: %w", err)
		}
	}
	// Before the volumes and the sources, per seedWorkingRoot: anything wired
	// onto the working root itself carries its own ownership.
	if err := b.seedWorkingRoot(bootstrap.WorkingRoot(sandboxPaths), id); err != nil {
		return fmt.Errorf("seed working root: %w", err)
	}
	if wire {
		volumes, err := loadResolvedVolumes(id, bootstrap.Volumes)
		if err != nil {
			return fmt.Errorf("resolve volumes: %w", err)
		}
		if err := b.wireVolumes(volumes, id); err != nil {
			return err
		}
		logger.Info("wired sandbox volumes", "count", len(volumes))
	}
	// Seed the home directory after the home volume (if any) is mounted, so the
	// skeleton lands on the persistent volume rather than the image layer.
	if err := b.seedHome(id); err != nil {
		return fmt.Errorf("seed home: %w", err)
	}
	// After seedHome: it fills only an empty home from /etc/skel, so a
	// .gitconfig written before it would leave the sandbox with no skeleton.
	if err := b.seedGitConfig(id, bootstrap.Git); err != nil {
		return fmt.Errorf("seed git config: %w", err)
	}
	// After seedHome for the same reason, and before wireSources only
	// because it reads the manifest's targets rather than the trees. It
	// writes straight to its final owner: nothing chowns home afterwards.
	if !b.off(featureDirenv) {
		if err := b.seedDirenvConfig(id, bootstrap.Sources); err != nil {
			return fmt.Errorf("seed direnv config: %w", err)
		}
	}
	// After seedHome for the same reason, and written straight to their
	// final owner.
	if !b.off(featureDesktop) {
		if err := b.seedDesktopLaunchers(id, desktop.LauncherDir); err != nil {
			return fmt.Errorf("seed desktop launchers: %w", err)
		}
	}
	if !wire {
		return nil
	}
	if err := b.wireSources(bootstrap.Sources, id); err != nil {
		return err
	}
	if len(bootstrap.Sources) > 0 {
		logger.Info("wired sandbox sources", "count", len(bootstrap.Sources))
	}
	return nil
}
}

// seedWorkingRoot creates the directory the sandbox works in and gives it to
// the sandbox user.
//
// Nothing else here reaches it. The image ships it (`mkdir -p /workspace` in a
// Dockerfile) root-owned, because the sandbox user does not exist until
// ensureUser above creates it, and wireSources chowns only the targets it
// binds -- which are directories *under* the working root, or somewhere else
// entirely when a source keeps its host path. So a sandbox created with
// --no-source, which has no source to bind at all, worked in a root-owned
// directory it could not write in.
//
// Only the directory itself, not a walk of it: everything under it is either a
// directory wireSources created and gave away with it (mkdirAllOwned), a source
// with the ownership wireSources gave it, or work the sandbox user made and
// already owns. Recursing into a checkout is a cost boot never pays.
//
// A working root inside home invents the directories between home and it, and
// those go to the user as well: nothing walks home to fix them up afterwards.
//
// Before wireVolumes and wireSources, so that a declared volume or a source
// bound onto the working root itself -- which is the primary source's default
// target -- states the ownership and this does not overwrite it.
func (b *booter) seedWorkingRoot(root string, id identity) error {
	if err := mkdirAllOwned(root, id.home, id.uid, id.gid); err != nil {
		return err
	}
	return os.Chown(root, id.uid, id.gid)
}

// wireSources bind-mounts each pool-agent-materialized source from
// /.discobox/sources/<slug> onto its manifest target, owned by the sandbox user.
//
// Ownership comes from the manifest only when the pool agent actually knew it;
// otherwise it comes from id, the identity this flow just resolved. The pool
// agent cannot resolve a sandbox's account (ADR 0025 §4), so when the manifest
// named no user there is nothing for it to publish -- which is why those
// fields are optional rather than plain ints. Absent arriving as 0 would make
// this chown hand the primary source tree to root, in precisely the case where
// the sandbox is least likely to be running as root (ADR 0033 §5).

